def verify_isbn(isbn: str) -> str:
    def calculate_isbn_checksum(isbn: str) -> str:
        total = 0
        for i, char in enumerate(isbn):
            if char == 'X':
                total += 10 * (10 - i)
            else:
                total += int(char) * (10 - i)
        return str(total % 11)

    parts = isbn.split('-')
    if len(parts) != 4:
        raise ValueError("Invalid ISBN format")

    body = '-'.join(parts[:3])
    provided_checksum = parts[3]
    correct_checksum = calculate_isbn_checksum(body)

    if provided_checksum == correct_checksum:
        return "Right"
    else:
        return f"{body}-{correct_checksum}"
