def count_passing_ways(n: int, m: int) -> int:
    MOD = 1000000007

    if n == 1:
        return 1

    dp = [[0] * (n + 1) for _ in range(m + 1)]
    dp[0][1], dp[0][2] = 1, 1

    for i in range(1, m + 1):
        for j in range(2, n + 1):
            dp[i][j] = (dp[i-1][j-1] + dp[i-1][j+1]) % MOD

    return dp[m][1]

