def max_energy(beads):
    n = len(beads)
    table = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            table[i][j] = max(table[i][k] + table[k + 1][j] + beads[i] * beads[k] * beads[j] for k in range(i, j))

