def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i in range(n + 1):
        coeff = coeffs[i]
        if coeff == 0:
            continue
        degree = n - i
        if degree == 0:
            term = str(abs(coeff))
        elif degree == 1:
            term = f"{abs(coeff)}x" if abs(coeff) != 1 else "x"
        else:
            term = f"{abs(coeff)}x^{degree}" if abs(coeff) != 1 else f"x^{degree}"
        if coeff < 0:
            term = "-" + term
        elif terms:
            term = "+" + term
        terms.append(term)
    return "".join(terms)

