def decode(encoded: str, original: str, message: str) -> str:
    # Check if the lengths match
    if len(encoded) != len(original):
        return "Failed"

    # Create a mapping from encoded letters to original letters
    mapping = {}
    for enc, orig in zip(encoded, original):
        if enc in mapping and mapping[enc] != orig:
            return "Failed"
        mapping[enc] = orig

    # Check if all letters are represented in the mapping
    if len(mapping) != len(set(encoded)):
        return "Failed"

    # Decode the message using the mapping
    decoded_message = ''.join(mapping.get(char, char) for char in message)
    return decoded_message
