def count_sequences(n: int, last: int, memo: dict) -> int:
    if n > last:
        return 0
    if n == 0 and last == 1:
        return 0
    if n == 0:
        return 1
    if last in memo:
        return memo[last]
    count = 1
    for i in range(1, (last // 2) + 1):
        count += count_sequences(i, i, memo)
    memo[last] = count
    return count
