def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """Evaluates the consistency of a scenario where one participant is the criminal based on the given statements."""

    # Remove statements about the day of the week
    for participant, _statements in statements.items():
        statements[participant] = [stmt for stmt in _statements if stmt.split()[0] not in days_of_week]

    # Check statements consistency
    for participant, _statements in statements.items():
        if participant in liar_count:
            if scenario in _statements:
                return False
        else:
            if scenario not in _statements:
                return False

    return True

