def catalan_number(n: int) -> int:
    if n <= 1:
        return 1

    # Initialize an array to store the Catalan numbers
    catalan = [0] * (n + 1)
    catalan[0] = 1

    # Calculate the Catalan numbers using dynamic programming
    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]
