def minimum_students_to_leave(heights): 
    n = len(heights) 
    if n <= 2: 
        return 0

    dp = [1] * n

    for i in range(1, n): 
        for j in range(i): 
            if heights[i] > heights[j]: 
                dp[i] = max(dp[i], dp[j] + 1)

    max_increase = max(dp)

    dp = [1] * n 

    for i in range(n-2, -1, -1): 
        for j in range(i+1, n): 
            if heights[i] > heights[j]: 
                dp[i] = max(dp[i], dp[j] + 1)

    max_decrease = max(dp[::-1])

    return n - (max_increase + max_decrease - 1)

